<div class="table-wrap"><table><thead><tr><th>Contrato / cliente</th><th>Servicio / monto</th><th>Estado</th><th>Siguiente tarea</th><th>Responsable / plazo</th><th></th></tr></thead><tbody>
<?php foreach ($tableContracts as $row): ?><tr><td><a class="contract-title" href="index.php?page=detail&amp;id=<?= e($row['id']) ?>"><?= e($row['title']) ?></a><small class="block"><?= e($row['code'] . ' · ' . $row['client']) ?></small></td><td><?= e($row['service']) ?><small class="block nowrap"><?= e($row['currency']) ?> <?= number_format((float) $row['amount'], 2) ?></small></td><td><span class="badge <?= e($row['status']) ?>"><?= e($statuses[$row['status']]) ?></span></td><td><?= e(taskLabel($row)) ?><small class="block"><?= e($row['status'] === 'review' ? $phases[(int) $row['stage']] : ($row['status'] === 'signed' ? 'Recorrido completado' : 'Comercial')) ?></small></td><td><?= e($row['assignee_name'] ?? '—') ?><?php if ($row['due_date']): ?><small class="block deadline <?= $row['due_date'] < date('Y-m-d') ? 'overdue' : '' ?>"><?= e($row['due_date']) ?> · <?= e(dueLabel($row['due_date'])) ?></small><?php endif ?></td><td><a href="index.php?page=detail&amp;id=<?= e($row['id']) ?>" aria-label="Ver <?= e($row['code']) ?>">→</a></td></tr><?php endforeach ?>
<?php if (!$tableContracts): ?><tr><td colspan="6" class="empty-state">No hay contratos pendientes o coincidentes en esta vista.</td></tr><?php endif ?></tbody></table></div>
